window.RP_SESSION={"id":"S-bf5be110f948","messages":[{"id":"RP-II-0154961","time":"2026-08-16T12:23:00+09:00","room":"RP II","name":"미상 화자 / 첫사랑 회상","profile":"올리브","identity":"reviewed","type":"dialogue","body":"내가 어설픈 용맹에서 돈을 모아 가장 먼저 한 것은, 그 아이의 정보를 찾는것이었다.","characters":[]},{"id":"RP-II-0154962","time":"2026-08-16T12:24:00+09:00","room":"RP II","name":"미상 화자 / 첫사랑 회상","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그것은 크게 어렵지 않았다. 나는 네 생김새와, 이름과, 네가 팔려간 곳과, 너를 사랑하는 마음을 여전히 기억하고 있어.","characters":[]},{"id":"RP-II-0154963","time":"2026-08-16T12:25:00+09:00","room":"RP II","name":"미상 화자 / 첫사랑 회상","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그리고 아아, 다시 실연이로다. 사랑은 이 생에 한 번 밖에 없었는데, 실연은 셋이로다.","characters":[]},{"id":"RP-II-0154964","time":"2026-08-16T12:29:00+09:00","room":"RP II","name":"미상 화자 / 첫사랑 회상","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 너는 내가 사람답게 살도록 만들어 주었지. 나의 가치가 도구로써 뿐만이 아님을 알려준 너는 어찌 도구로써 살았느냐.","characters":[]},{"id":"RP-II-0154965","time":"2026-08-16T12:29:00+09:00","room":"RP II","name":"미상 화자 / 첫사랑 회상","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그리하여 다시 실연이구나.","characters":[]},{"id":"RP-II-0154966","time":"2026-08-16T12:29:00+09:00","room":"RP II","name":"미상 화자 / 첫사랑 회상","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-II-0154967","time":"2026-08-16T12:29:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
